result={'status':'PASS' if all(x['status']=='PASS' for x in checks) else 'FAIL','checks':{'passed':sum(x['status']=='PASS' for x in checks),'failed':sum(x['status']=='FAIL' for x in checks),'total':len(checks)},'header':{'load_address':'0x0 observed field, no physical base claim','uncompressed_length':len(b),'entry_literal':'0x5E02D','entry_literal_in_payload':0x5e02d<len(b)},'anchors':{'pc_0x751e_to_literal_0x7540':hex(table_ptr),'pc_0x8188_to_known_string_0x820c':strings['0x820c'],'pc_0xb1f6_to_literal_0xb218':hex(callback_ptr),'known_strings':strings},'candidate_base_0x60000':{'table_pointer_offset':hex(table_off),'table_halfwords':[hex(x) for x in half],'callback_pointer_offset':hex(callback_off),'callback_bytes':callback_bytes.hex(),'callback_interpretation':'ASCII data, not a locally callable code prologue; universal base 0x60000 is falsified by callback coherence'},'conclusion':'Candidate base 0x60000 makes the classifier table pointer 0x6DB04 land on an 8-halfword structured array at payload 0xDB04, but maps callback pointer 0x67ABD (stored in callable slot +0x52C) to payload 0x7ABD, whose bytes are ASCII "lock Speed..." rather than code. Thus 0x60000 is not a coherent universal runtime base. Payload-relative offsets remain valid; actual loader relocation/runtime base remains unresolved.', 'limitations':['PC-relative string 0x820C is an internal payload anchor; strings 0x81D4/0x8271/0x828D are exact data offsets but no direct xref is promoted from mixed code/data disassembly.','No loader relocation table or runtime trace.','No units, clock, training, or hardware inference.'],'checks_detail':checks}
(OUT/'abl1-relocation-coherence-result.json').write_text(json.dumps(result,indent=2,sort_keys=True)+'\n');print(json.dumps({'status':result['status'],'checks':result['checks'],'candidate_base_0x60000':result['candidate_base_0x60000'],'conclusion':result['conclusion']},sort_keys=True));raise SystemExit(0 if result['status']=='PASS' else 1)
